import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/di/providers.dart';import '../data/auth_api_datasource.dart';import '../data/auth_repository_impl.dart';import '../domain/auth_repository.dart';import '../domain/entities/auth_session.dart';
final authRepositoryProvider=Provider<AuthRepository>((ref)=>AuthRepositoryImpl(AuthApiDatasource(ref.read(apiClientProvider)),ref.read(secureTokenStorageProvider)));final authSessionProvider=StateNotifierProvider<AuthNotifier,AuthSession?>((ref)=>AuthNotifier(ref.read(authRepositoryProvider),ref.read(secureTokenStorageProvider)));
class AuthNotifier extends StateNotifier<AuthSession?>{AuthNotifier(this.repo,this.storage):super(null);final AuthRepository repo;final dynamic storage;Future<void> login(String p,String pw)async=>state=await repo.login(p,pw);Future<Map<String,dynamic>> register({required String name,required String phone,String? email,required String password})=>repo.register(name:name,phone:phone,email:email,password:password);Future<void> verify(String p,String o)async=>state=await repo.verify(p,o);Future<void> logout()async{await repo.logout();state=null;}Future<bool> hasToken()async=>(await storage.readAccessToken())!=null;}
